        deploymentName,
        [...dischargeIds],
        enrichedResponse,
        (enrichedResponse.organizationId as string | undefined) ?? null
      );
    } else {
      // Non-terminal (delta / status): best-effort, not owner-gated.
      await this.queue.send("thread_response", enrichedResponse);
