/**
 * Behavior-run skill isolation (issue #2320 must-fix 1).
 *
 * A Behavior run executes the FROZEN instruction text its version compiled at
 * apply/save time. The agent's live skill library must not re-enter that turn:
 * the progressive catalog names skills the freeze never picked, and both the
 * catalog and the generic fallback tell the model to `cat .skills/*​/SKILL.md`,
 * which serves whatever the library says TODAY. Either one can dilute or
 * override the frozen text — so the freeze is only honest if the gateway stops
 * shipping the library on those turns.
 *
 * The discriminator is the SIGNED `source` claim on the worker token, stamped
 * `watcher-run` exactly when the dispatching session carried
 * `intent.kind === "behavior_run"` (routes/public/agent.ts). Ordinary chat —
 * including a chat turn a Behavior happens to be listening on — keeps the live
 * library; a human is in that conversation and the skills are theirs.
 *
 * These drive the real `/session-context` route through Hono so the assertions
 * cover the payload a worker actually receives (its `.skills` sync reads
 * `skillsConfig`; its system prompt concatenates `skillsInstructions`).
 */
import { beforeAll, describe, expect, test } from "bun:test";
import { randomBytes } from "node:crypto";

process.env.ENCRYPTION_KEY ??= randomBytes(32).toString("hex");

const { encrypt } = await import("@lobu/core");
const { WorkerGateway } = await import("../../gateway/gateway/index.js");

type Gateway = InstanceType<typeof WorkerGateway>;

const AGENT_ID = "agent-isolation";
const ORG_ID = "org-isolation";
const SKILL_CATALOG = `# Enabled Skills

- **pr-review** - Review a PR (\`local\`)

**To read full skill instructions:** \`cat .skills/*/SKILL.md\` to read the relevant SKILL.md file.`;

/** A worker token with no `jti`, so the revoked-token store (DB) is skipped. */
function mintToken(source?: string): string {
  return encrypt(
    JSON.stringify({
      tokenKind: "worker",
      userId: "user-1",
      conversationId: source ? "watcher-run-42" : "conv-chat-1",
      channelId: "api",
      agentId: AGENT_ID,
      organizationId: ORG_ID,
      deploymentName: "lobu-worker-test",
      timestamp: Date.now(),
      platform: "api",
      ...(source ? { source } : {}),
    })
  );
}

function buildGateway(): Gateway {
  const mcpConfigService = {
    getWorkerConfig: async () => ({ mcpServers: {} }),
  };
  const instructionService = {
    getSessionContext: async () => ({
      agentLayers: { identityMd: "", soulMd: "", userMd: "" },
      platformInstructions: "",
      networkInstructions: "",
      skillsInstructions: SKILL_CATALOG,
      mcpStatus: [],
    }),
  };
  const agentSettingsStore = {
    isDeclaredAgentScoped: async () => false,
    getSettings: async () => ({
      // Non-empty so `composeEffectiveModelRef` resolves without an org read.
      models: ["openai/gpt-5"],
      skillsConfig: {
        skills: [{ name: "pr-review", enabled: true, content: "REVIEW BODY" }],
      },
    }),
  };

  return new WorkerGateway(
    {} as never,
    "https://lobu.test",
    mcpConfigService as never,
    instructionService as never,
    undefined,
    undefined,
    agentSettingsStore as never
  );
}

async function fetchSessionContext(
  gateway: Gateway,
  token: string
): Promise<{ skillsConfig: unknown[]; skillsInstructions: string }> {
  const res = await gateway
    .getApp()
    .request("/session-context", {
      headers: { authorization: `Bearer ${token}` },
    });
  expect(res.status).toBe(200);
  return (await res.json()) as {
    skillsConfig: unknown[];
    skillsInstructions: string;
  };
}

let gateway: Gateway;
beforeAll(() => {
  gateway = buildGateway();
});

describe("worker session context — Behavior-run skill isolation", () => {
  test("a watcher-run turn gets no skill library", async () => {
    const body = await fetchSessionContext(gateway, mintToken("watcher-run"));

    // Nothing to sync into `.skills/`, so `cat .skills/…` has nothing to serve.
    expect(body.skillsConfig).toEqual([]);
    // And nothing tells the model to go looking for it either.
    expect(body.skillsInstructions).toBe("");
    expect(body.skillsInstructions).not.toContain("cat .skills");
  });

  test("an ordinary chat turn still gets the live skill library", async () => {
    const body = await fetchSessionContext(gateway, mintToken());

    expect(body.skillsConfig).toEqual([
      { name: "pr-review", content: "REVIEW BODY" },
    ]);
    expect(body.skillsInstructions).toContain("cat .skills");
  });

  test("a non-Behavior headless turn still gets the live skill library", async () => {
    // `connector-repair` / `scheduled-job` / `internal` are headless for SSE
    // routing, but they are not Behavior runs — no frozen version text drives
    // them, so stripping their skills would only make them dumber.
    const body = await fetchSessionContext(
      gateway,
      mintToken("connector-repair")
    );

    expect(body.skillsConfig).toHaveLength(1);
    expect(body.skillsInstructions).toContain("cat .skills");
  });
});

