// Enabled skills for worker filesystem sync. REUSE the org-scoped
// `agentSettings` fetched above — it is null for an orgless DB-backed agent
// (the correct fail-closed value: NO skill content leaks cross-tenant), and
// this removes the duplicate id-only read that ignored the org guard.
//
// A Behavior run is the exception: its job text is the frozen instruction
// body its version compiled at apply time, so the live library must not
// re-enter the turn. Both surfaces are dropped together — the catalog is
// what points the model at `.skills/`, and `skillsConfig` is what the
// worker syncs there for it to find (see `isBehaviorRunSession`).
const behaviorRun = isBehaviorRunSession(auth.tokenData.source);
let skillsConfig: Array<{ name: string; content: string }> = [];
const mcpContext: Record<string, string> = {};
if (agentSettings && !behaviorRun) {
  const skills = agentSettings.skillsConfig?.skills || [];
  skillsConfig = skills
    .filter((s) => s.enabled && s.content)
    .map((s) => ({ name: s.name, content: s.content! }));
}

const mergedSkillsInstructions = behaviorRun
  ? ""
  : contextData.skillsInstructions || "";

// The stamp the worker token carries and the session-context route
