// Reading versions off `args.behavior_id` directly meant an assignment made
// by create_from_version could list a version via get_versions and then fail
// to fetch it here.
const watcherRows = await sql`
  SELECT id, watcher_group_id, sources
  FROM watchers WHERE id = ${args.behavior_id}
