  // Since #2331 a Behavior's `prompt` is the compiled join of its skill
  // bodies, not authored text, so its `@`-tokens must not touch `sources`
  // (issue #2320 must-fix 2). Changing a source is an explicit act.
  const enc = (q: string) =>
    `#sql=${encodeURIComponent(q).replace(
      /[()'!*~]/g,
      (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`
    )}`;
  const oldQuery = "SELECT id FROM events WHERE payload_type = 'a'";
  const newQuery = "SELECT id FROM events WHERE payload_type = 'b'";

