import type { AgentSkillsCatalogItem } from "@/lib/api";

export type SkillBadge = "System" | "Packages";

export interface SkillCatalogPickerItem {
	key: string;
	name: string;
	description: string;
	badges: string[];
}

export function skillCapabilityBadges(
	item: Pick<AgentSkillsCatalogItem, "nixPackages" | "repo">,
): SkillBadge[] {
	const badges: SkillBadge[] = [];
	if (item.repo.startsWith("system/")) badges.push("System");
	const nixCount = item.nixPackages?.length ?? 0;
	if (nixCount > 0) badges.push("Packages");
	return badges;
}

export function buildSkillCatalogItems(
	catalog: AgentSkillsCatalogItem[],
	installedRepos: Set<string>,
): SkillCatalogPickerItem[] {
	return catalog
		.filter((item) => !item.hidden && !installedRepos.has(item.repo))
		.map((item) => ({
			key: item.repo,
			name: item.name,
			description:
				item.description ||
				item.instructions ||
				"Add this skill to give the agent tools and capabilities.",
			badges: skillCapabilityBadges(item),
		}));
}

export function filterSkillCatalog(
	items: SkillCatalogPickerItem[],
	query: string,
): SkillCatalogPickerItem[] {
	const q = query.trim().toLowerCase();
	if (!q) return items;
	return items.filter(
		(item) =>
			item.name.toLowerCase().includes(q) ||
			item.description.toLowerCase().includes(q) ||
			item.key.toLowerCase().includes(q),
	);
}

