export function useAgentSkillsCatalog(
	agentId?: string | null,
	options?: { enabled?: boolean },
) {
	const { slug } = getPathScope();

	return useQuery({
		queryKey: ["agent-skills-catalog", slug, agentId],
		queryFn: async (): Promise<AgentSkillsCatalogResponse> => {
			if (!slug || !agentId) {
				return { catalog: [], installedSkills: [] };
			}

			const res = await fetchWithTimeout(
				`${API_URL}/api/${slug}/installed/agents/${agentId}/installed?kinds=skills&include=catalog`,
				{ credentials: "include" },
			);
			await throwIfNotOk(res, "Failed to fetch skills catalog");
			const data = (await res.json()) as {
				installed?: {
					skills?: {
						items?: Array<{
							id: string;
							name: string;
							detail?: Record<string, unknown>;
						}>;
					};
				};
			};
			const items = data.installed?.skills?.items ?? [];

			const installedSkills = items
				.filter((item) => item.detail?.enabled !== undefined)
				.map((item) => ({
					repo: item.id,
					name: item.name,
					enabled: Boolean(item.detail?.enabled),
					description:
						typeof item.detail?.description === "string"
							? item.detail.description
							: undefined,
					system: Boolean(item.detail?.system),
					nixPackages: item.detail?.nix_packages as string[] | undefined,
				}));

			const catalog = items
				.filter((item) => !item.detail?.hidden)
				.map((item) => ({
					skillId: item.id.replace(/^bundled\//, ""),
					repo: item.id,
					name: item.name,
					description:
						typeof item.detail?.description === "string"
							? item.detail.description
							: undefined,
					instructions:
						typeof item.detail?.instructions === "string"
							? item.detail.instructions
							: undefined,
					hidden: false,
					nixPackages: item.detail?.nix_packages as string[] | undefined,
					installed: Boolean(item.detail?.installed),
				}));

			return { catalog, installedSkills };
		},
		enabled: !!slug && (options?.enabled ?? true),
		staleTime: 0,
		refetchOnMount: "always",
	});
}

