/**
 * Behavior instruction compile — the web mirror of `lobu apply`.
 *
 * A Behavior has no author-facing prompt (issue #2320). Instructions are the
 * ordered skill bodies of the owning agent, joined at save time and frozen into
 * the version. The server never sees `skills[]` — it stores only the compiled
 * text — so this module and the CLI's `compileBehaviorInstructions`
 * (`packages/cli/src/commands/_lib/apply/desired-state.ts`) must agree
 * byte-for-byte, or the same Behavior authored in the two surfaces would freeze
 * different instructions and churn versions against each other.
 *
 * The freeze is the honest part of the model: editing a skill afterwards does
 * NOT change an existing Behavior until it is saved again (an accepted limit in
 * #2320). Copy in the picker says so rather than implying a live link.
 */

/** Max skills a Behavior may reference. Mirrors `MAX_BEHAVIOR_SKILLS` (CLI). */
export const MAX_BEHAVIOR_SKILLS = 5;

/** Compiled-instruction ceiling. Mirrors `MAX_COMPILED_INSTRUCTIONS_BYTES`. */
export const MAX_COMPILED_INSTRUCTIONS_BYTES = 32 * 1024;

/** A skill the picker can offer: a library entry with a usable body. */
export interface BehaviorSkillOption {
	name: string;
	description?: string;
	/**
	 * Authored body. Custom skills carry `content`; bundled/system skills carry
	 * the catalog's `instructions`. The CLI only ever resolves files into
	 * `content`, so it has no equivalent fallback.
	 */
	content?: string;
	instructions?: string;
	enabled: boolean;
}

/** The body a skill contributes to the compile, or "" when it has none. */
export function skillBody(skill: BehaviorSkillOption): string {
	return (skill.content ?? skill.instructions ?? "").trim();
}

/** Skills that can actually be compiled: enabled and carrying a body. */
export function selectableSkills(
	library: BehaviorSkillOption[],
): BehaviorSkillOption[] {
	return library.filter((skill) => skill.enabled && skillBody(skill) !== "");
}

/** Trigger shape this module needs. Extra keys are ignored. */
export interface BehaviorTriggerLike {
	kind?: string;
	execution?: string;
}

/**
 * Whether the Behavior runs on its compiled instructions alone.
 *
 * An event trigger executing as "turn" carries its own content (the incoming
 * message/event) and may run with zero skills on the built-in default.
 * Everything else — schedule triggers, event triggers with execution "window",
 * and Behaviors with no triggers at all (manual runs) — has nothing but its
 * instructions, so it needs at least one skill. Mirrors `assertBehaviorSkills`.
 */
export function behaviorRequiresSkills(
	triggers: BehaviorTriggerLike[] | undefined,
): boolean {
	const list = triggers ?? [];
	if (list.length === 0) return true;
	return list.some(
		(trigger) => trigger.kind === "schedule" || trigger.execution === "window",
	);
}

/**
 * Join the selected skill bodies in order. Returns "" for an empty selection —
 * the event-turn case, where the server applies its built-in default.
 */
export function compileBehaviorInstructions(
	selected: string[],
	library: BehaviorSkillOption[],
): string {
	if (selected.length === 0) return "";
	const byName = new Map(library.map((skill) => [skill.name, skill]));
	const bodies: string[] = [];
	for (const name of selected) {
		const skill = byName.get(name);
		const body = skill ? skillBody(skill) : "";
		if (body) bodies.push(body);
	}
	return bodies.join("\n\n");
}

/** UTF-8 byte length of the compiled text (the cap is bytes, not characters). */
export function compiledByteLength(compiled: string): number {
	return new TextEncoder().encode(compiled).length;
}

/**
 * Validate a selection against the same rules `lobu apply` enforces, so the web
 * cannot author a Behavior the CLI would reject. Returns null when valid.
 */
export function validateBehaviorSkills(
	selected: string[],
	library: BehaviorSkillOption[],
	triggers: BehaviorTriggerLike[] | undefined,
): string | null {
	const duplicates = selected.filter(
		(name, i) => selected.indexOf(name) !== i,
	);
	if (duplicates.length > 0) {
		return `Duplicate skill: ${[...new Set(duplicates)].join(", ")} — the compile is ordered, so each skill may appear once.`;
	}
	if (selected.length > MAX_BEHAVIOR_SKILLS) {
		return `${selected.length} skills selected — the maximum is ${MAX_BEHAVIOR_SKILLS}.`;
	}
	const byName = new Map(library.map((skill) => [skill.name, skill]));
	for (const name of selected) {
		const skill = byName.get(name);
		if (!skill) {
			return `Skill "${name}" is no longer in this agent's library.`;
		}
		if (!skill.enabled) {
			return `Skill "${name}" is disabled — enable it on the agent or remove it here.`;
		}
		if (skillBody(skill) === "") {
			return `Skill "${name}" has an empty body — compiled instructions need text.`;
		}
	}
	if (behaviorRequiresSkills(triggers) && selected.length === 0) {
		return "Add at least one skill: schedules, window triggers, and Behaviors with no trigger run on their compiled instructions alone.";
	}
	const bytes = compiledByteLength(
		compileBehaviorInstructions(selected, library),
	);
	if (bytes > MAX_COMPILED_INSTRUCTIONS_BYTES) {
		return `These skills compile to ${Math.round(bytes / 1024)}KB of instructions — the maximum is ${MAX_COMPILED_INSTRUCTIONS_BYTES / 1024}KB.`;
	}
	return null;
}

import { describe, expect, it } from "vitest";
import {
	type BehaviorSkillOption,
	behaviorRequiresSkills,
	compileBehaviorInstructions,
	compiledByteLength,
	MAX_BEHAVIOR_SKILLS,
	MAX_COMPILED_INSTRUCTIONS_BYTES,
	selectableSkills,
	validateBehaviorSkills,
} from "./behavior-skills";

const skill = (
	name: string,
	over: Partial<BehaviorSkillOption> = {},
): BehaviorSkillOption => ({
	name,
	content: `body of ${name}`,
	enabled: true,
	...over,
});

const LIBRARY = [skill("triage"), skill("sql-style"), skill("digest")];

describe("compileBehaviorInstructions", () => {
	it("joins bodies in selection order with a blank line", () => {
		expect(
			compileBehaviorInstructions(["sql-style", "triage"], LIBRARY),
		).toBe("body of sql-style\n\nbody of triage");
	});

	it("returns empty text for an empty selection (the event-turn default)", () => {
		expect(compileBehaviorInstructions([], LIBRARY)).toBe("");
	});

	it("trims each body so the join is exactly one blank line", () => {
		const padded = [skill("a", { content: "\n  alpha  \n\n" }), skill("b")];
		expect(compileBehaviorInstructions(["a", "b"], padded)).toBe(
			"alpha\n\nbody of b",
		);
	});

	it("falls back to catalog instructions when a skill has no content", () => {
		const bundled = [
			skill("sys", { content: undefined, instructions: "bundled body" }),
		];
		expect(compileBehaviorInstructions(["sys"], bundled)).toBe("bundled body");
	});
});

describe("behaviorRequiresSkills", () => {
	it("requires a skill when there are no triggers (manual runs)", () => {
		expect(behaviorRequiresSkills([])).toBe(true);
		expect(behaviorRequiresSkills(undefined)).toBe(true);
	});

	it("requires a skill for a schedule trigger", () => {
		expect(behaviorRequiresSkills([{ kind: "schedule" }])).toBe(true);
	});

	it("requires a skill for an event trigger executing as a window", () => {
		expect(
			behaviorRequiresSkills([{ kind: "event", execution: "window" }]),
		).toBe(true);
	});

	it("allows zero skills for an event trigger executing as a turn", () => {
		expect(
			behaviorRequiresSkills([{ kind: "event", execution: "turn" }]),
		).toBe(false);
	});

	it("requires a skill when any one of several triggers needs it", () => {
		expect(
			behaviorRequiresSkills([
				{ kind: "event", execution: "turn" },
				{ kind: "schedule" },
			]),
		).toBe(true);
	});
});

describe("validateBehaviorSkills", () => {
	const turn = [{ kind: "event", execution: "turn" }];
	const schedule = [{ kind: "schedule" }];

	it("accepts a valid ordered selection", () => {
		expect(validateBehaviorSkills(["triage"], LIBRARY, schedule)).toBeNull();
	});

	it("accepts zero skills on an event-turn Behavior", () => {
		expect(validateBehaviorSkills([], LIBRARY, turn)).toBeNull();
	});

	it("rejects zero skills when the Behavior runs on instructions alone", () => {
		expect(validateBehaviorSkills([], LIBRARY, schedule)).toMatch(
			/at least one skill/i,
		);
	});

	it("rejects a duplicate skill", () => {
		expect(
			validateBehaviorSkills(["triage", "triage"], LIBRARY, schedule),
		).toMatch(/Duplicate skill: triage/);
	});

	it("rejects more than the maximum number of skills", () => {
		const many = Array.from({ length: MAX_BEHAVIOR_SKILLS + 1 }, (_, i) =>
			skill(`s${i}`),
		);
		const names = many.map((s) => s.name);
		expect(validateBehaviorSkills(names, many, schedule)).toMatch(
			new RegExp(`maximum is ${MAX_BEHAVIOR_SKILLS}`),
		);
	});

	it("rejects a skill that left the library", () => {
		expect(validateBehaviorSkills(["gone"], LIBRARY, schedule)).toMatch(
			/no longer in this agent's library/,
		);
	});

	it("rejects a disabled skill", () => {
		const lib = [skill("off", { enabled: false })];
		expect(validateBehaviorSkills(["off"], lib, schedule)).toMatch(
			/disabled/,
		);
	});

	it("rejects a skill with an empty body", () => {
		const lib = [skill("blank", { content: "   " })];
		expect(validateBehaviorSkills(["blank"], lib, schedule)).toMatch(
			/empty body/,
		);
	});

	it("rejects a selection that compiles past the byte ceiling", () => {
		const big = [skill("big", { content: "x".repeat(MAX_COMPILED_INSTRUCTIONS_BYTES + 1) })];
		expect(validateBehaviorSkills(["big"], big, schedule)).toMatch(
			/maximum is 32KB/,
		);
	});

	it("measures the ceiling in UTF-8 bytes, not characters", () => {
		// "é" is one character but two UTF-8 bytes — a character-based check would
		// let this selection through.
		const half = MAX_COMPILED_INSTRUCTIONS_BYTES / 2;
		const lib = [skill("multi", { content: "é".repeat(half + 1) })];
		expect(compiledByteLength("é")).toBe(2);
		expect(validateBehaviorSkills(["multi"], lib, schedule)).toMatch(
			/maximum is 32KB/,
		);
	});
});

describe("selectableSkills", () => {
	it("hides disabled and body-less skills from the picker", () => {
		const lib = [
			skill("ok"),
			skill("disabled", { enabled: false }),
			skill("empty", { content: "" }),
		];
		expect(selectableSkills(lib).map((s) => s.name)).toEqual(["ok"]);
	});
});

