import { ArrowDown, ArrowUp, Plus, X } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { CommandItem } from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
	type BehaviorSkillOption,
	MAX_BEHAVIOR_SKILLS,
	selectableSkills,
} from "@/lib/behavior-skills";

/**
 * Ordered skill picker — the Behavior's instruction authoring surface.
 *
 * Order is meaningful: the bodies are joined top-to-bottom into the frozen
 * version text, so the list is reorderable rather than a plain multi-select.
 */
export function BehaviorSkillsPicker({
	library,
	selected,
	onChange,
	required,
	disabled,
	error,
}: {
	library: BehaviorSkillOption[];
	selected: string[];
	onChange: (next: string[]) => void;
	/** Whether this Behavior runs on its instructions alone (needs ≥1 skill). */
	required: boolean;
	disabled?: boolean;
	error?: string | null;
}) {
	const available = selectableSkills(library);
	const byName = new Map(available.map((skill) => [skill.name, skill]));
	const unselected = available.filter((skill) => !selected.includes(skill.name));
	const atCap = selected.length >= MAX_BEHAVIOR_SKILLS;

	const move = (index: number, delta: number) => {
		const target = index + delta;
		if (target < 0 || target >= selected.length) return;
		const next = [...selected];
		[next[index], next[target]] = [next[target], next[index]];
		onChange(next);
	};

	return (
		<div className="space-y-2">
			<div className="flex items-center justify-between gap-3">
				<Label htmlFor="behavior-skills-add">
					Skills{" "}
					{required ? (
						<span className="text-destructive">*</span>
					) : (
						<span className="text-xs font-normal text-muted-foreground">
							(optional)
						</span>
					)}
				</Label>
				<span className="text-xs text-muted-foreground">
					{selected.length}/{MAX_BEHAVIOR_SKILLS}
				</span>
			</div>

			{selected.length > 0 ? (
				<ol className="space-y-2">
					{selected.map((name, index) => {
						const skill = byName.get(name);
						return (
							<li
								key={name}
								className="flex items-start gap-2 rounded-lg border bg-background p-2"
							>
								<span className="mt-1 w-4 shrink-0 text-center text-xs text-muted-foreground">
									{index + 1}
								</span>
								<div className="min-w-0 flex-1">
									<div className="flex items-center gap-2">
										<span className="truncate text-sm font-medium">{name}</span>
										{!skill ? (
											<Badge variant="destructive" className="shrink-0">
												Unavailable
											</Badge>
										) : null}
									</div>
									{skill?.description ? (
										<p className="truncate text-xs text-muted-foreground">
											{skill.description}
										</p>
									) : null}
								</div>
								<div className="flex shrink-0 items-center">
									<Button
										type="button"
										variant="ghost"
										size="icon"
										className="h-7 w-7"
										aria-label={`Move ${name} up`}
										disabled={disabled || index === 0}
										onClick={() => move(index, -1)}
									>
										<ArrowUp className="h-3.5 w-3.5" />
									</Button>
									<Button
										type="button"
										variant="ghost"
										size="icon"
										className="h-7 w-7"
										aria-label={`Move ${name} down`}
										disabled={disabled || index === selected.length - 1}
										onClick={() => move(index, 1)}
									>
										<ArrowDown className="h-3.5 w-3.5" />
									</Button>
									<Button
										type="button"
										variant="ghost"
										size="icon"
										className="h-7 w-7"
										aria-label={`Remove ${name}`}
										disabled={disabled}
										onClick={() =>
											onChange(selected.filter((s) => s !== name))
										}
									>
										<X className="h-3.5 w-3.5" />
									</Button>
								</div>
							</li>
						);
					})}
				</ol>
			) : null}

			<Combobox
				searchPlaceholder="Search skills…"
				emptyText={
					available.length === 0
						? "This agent has no skills with instructions yet."
						: "No matching skill."
				}
				trigger={() => (
					<Button
						type="button"
						id="behavior-skills-add"
						variant="outline"
						size="sm"
						className="w-full justify-start"
						disabled={disabled || atCap || unselected.length === 0}
					>
						<Plus className="mr-2 h-3.5 w-3.5" />
						{atCap
							? `Maximum ${MAX_BEHAVIOR_SKILLS} skills`
							: selected.length > 0
								? "Add another skill"
								: "Add a skill"}
					</Button>
				)}
			>
				{(close) =>
					unselected.map((skill) => (
						<CommandItem
							key={skill.name}
							value={`${skill.name} ${skill.description ?? ""}`}
							onSelect={() => {
								onChange([...selected, skill.name]);
								close();
							}}
						>
							<div className="min-w-0">
								<div className="truncate text-sm">{skill.name}</div>
								{skill.description ? (
									<div className="truncate text-xs text-muted-foreground">
										{skill.description}
									</div>
								) : null}
							</div>
						</CommandItem>
					))
				}
			</Combobox>

			{error ? (
				<p className="text-xs text-destructive">{error}</p>
			) : (
				<p className="text-xs text-muted-foreground">
					{required
						? "Runs on these instructions alone, joined in order. "
						: "Optional — with none, the agent handles the incoming event on its default instruction. "}
					Saving freezes the skill text into this version; later edits to a
					skill do not change this Behavior until you save it again.
				</p>
			)}
		</div>
	);
}

