import { Code2, Plus, X } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { CommandItem } from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import { useOrgContext } from "@/hooks/use-org-context";
import { useReferenceSearch } from "@/lib/api/references";
import {
	behaviorSourcesWithRef,
	type LobuRefKind,
	sqlRefPath,
} from "@/lib/references";
import { SqlSourceDialog, type SqlSourceValue } from "./sql-source-dialog";

/** Object kinds that can back a Behavior source. */
const SOURCE_KINDS: LobuRefKind[] = [
	"entity",
	"connection",
	"connector",
	"feed",
	"metric",
];

export interface BehaviorSource {
	name: string;
	query: string;
}

/**
 * The Behavior's data sources, authored on their own.
 *
 * Sources used to be a side effect of `@`-chips in the goal field. #2320 takes
 * the goal away (instructions are compiled skills now), and sources stay
 * Behavior-owned — skills never author them — so they need a surface of their
 * own rather than disappearing with the prompt.
 */
export function BehaviorSourcesEditor({
	sources,
	onChange,
	disabled,
}: {
	sources: BehaviorSource[];
	onChange: (next: BehaviorSource[]) => void;
	disabled?: boolean;
}) {
	const { currentOwner, resolvedOrganizationId } = useOrgContext();
	const [query, setQuery] = useState("");
	const [sqlOpen, setSqlOpen] = useState(false);

	const { refs } = useReferenceSearch({
		owner: currentOwner,
		organizationId: resolvedOrganizationId,
		kinds: SOURCE_KINDS,
		query,
	});

	const addSql = (value: SqlSourceValue) => {
		onChange(
			behaviorSourcesWithRef(
				{
					kind: "sql",
					id: "",
					label: value.name,
					path: sqlRefPath(value.query),
				},
				sources,
			),
		);
	};

	return (
		<div className="space-y-2">
			<Label>Sources</Label>

			{sources.length > 0 ? (
				<ul className="space-y-2">
					{sources.map((source) => (
						<li
							key={source.query}
							className="flex items-start gap-2 rounded-lg border bg-background p-2"
						>
							<div className="min-w-0 flex-1">
								<div className="truncate font-mono text-xs font-medium">
									{source.name}
								</div>
								<div className="truncate text-xs text-muted-foreground">
									{source.query}
								</div>
							</div>
							<Button
								type="button"
								variant="ghost"
								size="icon"
								className="h-7 w-7 shrink-0"
								aria-label={`Remove source ${source.name}`}
								disabled={disabled}
								onClick={() =>
									onChange(sources.filter((s) => s.query !== source.query))
								}
							>
								<X className="h-3.5 w-3.5" />
							</Button>
						</li>
					))}
				</ul>
			) : null}

			<div className="flex gap-2">
				<Combobox
					searchPlaceholder="Search feeds, connections, metrics…"
					emptyText="No matching reference."
					onQueryChange={setQuery}
					trigger={() => (
						<Button
							type="button"
							variant="outline"
							size="sm"
							disabled={disabled}
						>
							<Plus className="mr-2 h-3.5 w-3.5" />
							Add source
						</Button>
					)}
				>
					{(close) =>
						refs.map((ref) => (
							<CommandItem
								key={`${ref.kind}:${ref.id}`}
								value={`${ref.label} ${ref.kind}`}
								onSelect={() => {
									onChange(behaviorSourcesWithRef(ref, sources));
									close();
								}}
							>
								<span className="truncate text-sm">{ref.label}</span>
								<span className="ml-2 shrink-0 text-xs text-muted-foreground">
									{ref.kind}
								</span>
							</CommandItem>
						))
					}
				</Combobox>

				<Button
					type="button"
					variant="outline"
					size="sm"
					disabled={disabled}
					onClick={() => setSqlOpen(true)}
				>
					<Code2 className="mr-2 h-3.5 w-3.5" />
					Add SQL
				</Button>
			</div>

			<p className="text-xs text-muted-foreground">
				Data handed to the agent alongside its instructions. Behavior-owned —
				skills never add or remove sources.
			</p>

			<SqlSourceDialog
				open={sqlOpen}
				onOpenChange={setSqlOpen}
				onSubmit={addSql}
			/>
		</div>
	);
}

