export function Combobox({
	trigger,
	searchPlaceholder,
	emptyText,
	contentClassName,
	align = "start",
	onQueryChange,
	children,
}: {
	trigger: (open: boolean) => ReactNode;
	searchPlaceholder: string;
	emptyText: ReactNode;
	contentClassName?: string;
	align?: "start" | "center" | "end";
	/**
	 * Observe the search text. Callers whose options come from a server-side
	 * search need the query outside `children` (to drive the fetch); the ones
	 * filtering a list already in memory can ignore it and let cmdk match on
	 * each item's `value`.
	 */
	onQueryChange?: (query: string) => void;
	children: (close: () => void, query: string) => ReactNode;
}) {
	const [open, setOpen] = useState(false);
	const [query, setQuery] = useState("");
	const updateQuery = (next: string) => {
		setQuery(next);
		onQueryChange?.(next);
	};
	return (
		<Popover
			open={open}
			onOpenChange={(next) => {
				setOpen(next);
				if (!next) updateQuery("");
			}}
		>
			<PopoverTrigger asChild>{trigger(open)}</PopoverTrigger>
			<PopoverContent className={cn("p-0", contentClassName)} align={align}>
				<Command>
					<CommandInput
						placeholder={searchPlaceholder}
						value={query}
						onValueChange={updateQuery}
					/>
					<CommandList>
						<CommandEmpty>{emptyText}</CommandEmpty>
						<CommandGroup>
							{children(() => {
								setOpen(false);
								updateQuery("");
							}, query)}
						</CommandGroup>
					</CommandList>
				</Command>
			</PopoverContent>
		</Popover>
	);
}

