import { describe, expect, it } from "vitest";
import { behaviorSourcesWithRef, type LobuRef } from "@/lib/references";
import { SOURCE_KINDS } from "./behavior-sources-editor";

/**
 * The picker and the ref→source codec are two lists that must agree. When they
 * drifted, selecting the odd kind closed the popover and added nothing — no
 * error, no row, nothing to notice. `entity` shipped that way once (it is a
 * scoping reference, never a source), so this walks the offered list instead of
 * spot-checking a kind.
 */
describe("SOURCE_KINDS", () => {
	it.each(SOURCE_KINDS)("%s produces a source when picked", (kind) => {
		const ref: LobuRef = {
			kind,
			id: kind === "metric" ? "company.revenue" : "42",
			label: `A ${kind}`,
			path: `/${kind}/42`,
		};
		const next = behaviorSourcesWithRef(ref, []);
		expect(next).toHaveLength(1);
		expect(next[0].query).not.toBe("");
	});

	it("does not offer entity — it scopes the Behavior, it is not a source", () => {
		expect(SOURCE_KINDS).not.toContain("entity");
		// And the codec agrees, so a future re-add fails the case above too.
		expect(
			behaviorSourcesWithRef(
				{ kind: "entity", id: "42", label: "Acme", path: "/entity/42" },
				[],
			),
		).toEqual([]);
	});

	it("adds a SQL source from an inline query path", () => {
		const next = behaviorSourcesWithRef(
			{
				kind: "sql",
				id: "",
				label: "Recent events",
				path: "#sql=SELECT%20id%20FROM%20events",
			},
			[],
		);
		expect(next).toEqual([
			{ name: "recent_events", query: "SELECT id FROM events" },
		]);
	});

	it("ignores a duplicate query rather than adding a second row", () => {
		const first = behaviorSourcesWithRef(
			{ kind: "feed", id: "7", label: "Inbox", path: "/feed/7" },
			[],
		);
		const again = behaviorSourcesWithRef(
			{ kind: "feed", id: "7", label: "Inbox", path: "/feed/7" },
			first,
		);
		expect(again).toEqual(first);
	});

	it("uniquifies a colliding name so both sources survive", () => {
		const first = behaviorSourcesWithRef(
			{ kind: "feed", id: "7", label: "Inbox", path: "/feed/7" },
			[],
		);
		const second = behaviorSourcesWithRef(
			{ kind: "feed", id: "8", label: "Inbox", path: "/feed/8" },
			first,
		);
		expect(second.map((s) => s.name)).toEqual(["inbox", "inbox_2"]);
	});
});

