      RETURNING watcher_id, approved_input->>'dispatch_source' AS dispatch_source
    `;
		if (!failed) return;
		await advanceScheduleAfterTerminalFailure(
			tx,
			failed.watcher_id == null ? null : Number(failed.watcher_id),
			failed.dispatch_source
		);
	});
}

